{"version":3,"file":"http.js","sources":["api/http.js"],"sourcesContent":["// let baseUrl = 'http://123.56.43.103:8088'\nlet baseUrl = 'https://joinup.org.cn/api'\nimport { useUserStore } from '../stores/user.js'\n// 给参数 data 设置了一个默认值，即一个空对象 {}\nexport default function http(url1, data = {}, method) {\n  \n  return new Promise((resolve, reject) => {\n    uni.request({\n      url:baseUrl + url1,\n      data,\n      method:method,\n      header:{\n        'Content-Type': 'application/json',\n        'Authorization':   uni.getStorageSync('token') || ''\n      },\n      \n      success: res => {\n        if (res.statusCode == 200) {\n          if(data=='r'||url1==\"/user/verify\"||url1==\"/course/task/add\"){\n            resolve(res.data)\n          }else{\n            if (res.data.code == 1) {\n              resolve(res.data.data)\n            } else if (res.data.code == 0) {\n              uni.showToast({\n                title:res.data.msg,\n                icon:'none'\n              })\n              reject(res.data.msg)\n            }\n          }\n          \n        }\n      },\n      \n      fail: () => {\n        console.log(\"服务器请求错误\")\n        uni.showToast({\n          title:'服务器请求错误',\n          icon:'none'\n        })\n      }\n    })\n  })\n}\n\n"],"names":["uni"],"mappings":";;;AACA,IAAI,UAAU;AAGC,SAAS,KAAK,MAAM,OAAO,CAAA,GAAI,QAAQ;AAEpD,SAAO,IAAI,QAAQ,CAAC,SAAS,WAAW;AACtCA,kBAAAA,MAAI,QAAQ;AAAA,MACV,KAAI,UAAU;AAAA,MACd;AAAA,MACA;AAAA,MACA,QAAO;AAAA,QACL,gBAAgB;AAAA,QAChB,iBAAmBA,cAAG,MAAC,eAAe,OAAO,KAAK;AAAA,MACnD;AAAA,MAED,SAAS,SAAO;AACd,YAAI,IAAI,cAAc,KAAK;AACzB,cAAG,QAAM,OAAK,QAAM,kBAAgB,QAAM,oBAAmB;AAC3D,oBAAQ,IAAI,IAAI;AAAA,UAC5B,OAAe;AACH,gBAAI,IAAI,KAAK,QAAQ,GAAG;AACtB,sBAAQ,IAAI,KAAK,IAAI;AAAA,YACtB,WAAU,IAAI,KAAK,QAAQ,GAAG;AAC7BA,4BAAAA,MAAI,UAAU;AAAA,gBACZ,OAAM,IAAI,KAAK;AAAA,gBACf,MAAK;AAAA,cACrB,CAAe;AACD,qBAAO,IAAI,KAAK,GAAG;AAAA,YACpB;AAAA,UACF;AAAA,QAEF;AAAA,MACF;AAAA,MAED,MAAM,MAAM;AACVA,sBAAAA,MAAA,MAAA,OAAA,qBAAY,SAAS;AACrBA,sBAAAA,MA